const axisLabelsArray   = ['Jan', 'Feb', 'Mar'];          // <-- your X‑axis labels
const dataPointsArray   = [10, 20, 30];                   // <-- your Y‑axis data
const defaultColor      = '#007bff';                      // <-- your preferred color
const chartLayoutObject = {                                 // <-- your chart config
  title: 'Monthly Sales',
  xAxis: { title: 'Month' },
  yAxis: { title: 'Revenue ($)' }
};

// 2️⃣  Call the helper – note that arrays/objects must be passed as JSON strings
