  labels: JSON.stringify(axisLabelsArray),     // → stringified array
  data:   JSON.stringify(dataPointsArray),     // → stringified array
  color:  defaultColor,                        // → plain string (optional)
  chartLayout: JSON.stringify(chartLayoutObject) // → stringified object
});

// 3️⃣  Inspect the return value – it usually contains the updated layout or the new series
console.log('Result from ChartSeriesGenerator:', result);
```

